 T(1, IDX, 'colors = ["red", "green", "blue", "pink"]\nprint(colors[1], colors[-1])\nprint(colors[1:3])', "Indexes start at 0, and `-1` is the last item. A slice `[1:3]` gives a new list with items 1 and 2."),
 W(1, WHAT, 'Make a list `cities` with `"Delhi"`, `"Pune"` and `"Goa"`. Print the list and its length with one `print()`.', '# Make the list\n', 'cities = ["Delhi", "Pune", "Goa"]\nprint(cities, len(cities))', "Square brackets make a list, and `len()` counts its items."),
 W(1, ADD, '`cart = ["rice", "dal"]`. Add `"oil"` at the end and `"salt"` at the start. Print the cart.', 'cart = ["rice", "dal"]\n', 'cart = ["rice", "dal"]\ncart.append("oil")\ncart.insert(0, "salt")\nprint(cart)', "`append()` adds to the end. `insert(0, x)` puts `x` at position 0, the front."),
 W(1, REM, '`stock = ["pen", "ink", "pad", "ink"]`. Remove the first `"ink"` with `remove()`, then remove the last item with `pop()`. Print the list.', 'stock = ["pen", "ink", "pad", "ink"]\n', 'stock = ["pen", "ink", "pad", "ink"]\nstock.remove("ink")\nstock.pop()\nprint(stock)', "`remove(x)` deletes the first match only. `pop()` with no index removes the last item."),
 W(1, BUILT, '`sales = [450, 120, 780, 340]`. Print the total, the smallest and the largest value with one `print()`.', 'sales = [450, 120, 780, 340]\n', 'sales = [450, 120, 780, 340]\nprint(sum(sales), min(sales), max(sales))', "`sum()`, `min()` and `max()` work on a whole list at once, no loop needed."),
 F(1, ADD, "This code should print `['apple', 'banana', 'cherry']`, but it crashes. Fix it.", 'fruits = ["apple", "banana"]\nfruits.add("cherry")\nprint(fruits)', 'fruits = ["apple", "banana"]\nfruits.append("cherry")\nprint(fruits)', "Lists have no `add()` method (that one belongs to sets). Use `append()` to add to the end of a list."),
 T(1, FIND, 'tags = ["sql", "python", "excel", "python"]\nprint(tags.index("python"), tags.count("python"), "R" in tags)', "`index()` gives the position of the first match (1). `count()` counts all matches. `in` gives `True` or `False`."),
 F(1, IDX, "This code should print the last mark, `72`, but it crashes. Fix it.", 'marks = [56, 89, 72]\nprint(marks[3])', 'marks = [56, 89, 72]\nprint(marks[-1])', "A list of 3 items has indexes 0, 1 and 2, so index 3 is out of range. `[-1]` always gives the last item."),
 # ---------- Medium ----------
 W(2, SORT, '`prices = [499, 120, 999, 250, 75]`. Print the 2 cheapest prices, using `sorted()` and a slice.', 'prices = [499, 120, 999, 250, 75]\n', 'prices = [499, 120, 999, 250, 75]\nprint(sorted(prices)[:2])', "`sorted()` gives a new list from smallest to largest, and `[:2]` keeps the first two."),
 F(2, SORT, "This code should print `[1, 2, 3]`, but it prints `None`. Fix it.", 'nums = [3, 1, 2]\nnums = nums.sort()\nprint(nums)', 'nums = [3, 1, 2]\nnums.sort()\nprint(nums)', "`sort()` changes the list in place and returns `None`. Do not store its result. (Or use `nums = sorted(nums)`.)"),
 T(2, COPY, 'a = [1, 2, 3]\nb = a\nc = a.copy()\nb.append(4)\nprint(a, c)', "`b = a` makes a second name for the same list, so changing `b` changes `a`. `copy()` makes a separate list."),
 W(2, LOOP, '`names = ["asha", "ravi", "neha"]`. Print each name in capitals with its number: `1. ASHA`, `2. RAVI`, `3. NEHA`.', 'names = ["asha", "ravi", "neha"]\n', 'names = ["asha", "ravi", "neha"]\nfor num, name in enumerate(names, start=1):\n    print(f"{num}. {name.upper()}")', "`enumerate(..., start=1)` gives the number and the item. `upper()` makes the capitals."),
 W(2, NEST, '`sales = [[120, 80], [200, 150], [90, 60]]` (one row per day, one column per shop). Print the sales of shop 2 on day 3, and the total of day 2, with one `print()`.', 'sales = [[120, 80], [200, 150], [90, 60]]\n', 'sales = [[120, 80], [200, 150], [90, 60]]\nprint(sales[2][1], sum(sales[1]))', "The first index picks the row (day 3 is index 2) and the second picks the column (shop 2 is index 1). `sales[1]` is the whole day 2 row."),
 W(2, COMP, '`temps = [31, 35, 29, 38, 33]`. Use a list comprehension to keep only the temperatures above 32, and print the new list.', 'temps = [31, 35, 29, 38, 33]\n', 'temps = [31, 35, 29, 38, 33]\nprint([t for t in temps if t > 32])', "`[t for t in temps if t > 32]` is a loop and a filter in one line."),
